entries[322101] = { ["name"] = "Schadensumleitung", ["text"] = "15 Energie / 1.4% von Grundmana 100 Meter Reichweite\nSofort 15 sek. Abklingzeit\nNebelwirker ( Nebelwirkermönch )\nStößt negatives Chi aus Eurem Körper, was Euch um (120% der Zaubermacht) Gesundheit heilt und einem Gegner innerhalb von 20 Metern 25% des geheilten Werts als Naturschaden zufügt.\n\nBraumeister, Windläufer\nStößt negatives Chi aus Eurem Körper, was Euch um (120% der Zaubermacht) Gesundheit heilt und einem Gegner innerhalb von 20 Metern 10% des geheilten Werts als Naturschaden zufügt. [ Schadensumleitung : Entzieht all Euren heilenden Sphären positives Chi, um die Heilung durch 'Schadensumleitung' zu erhöhen ] [ Schadensumkehr : Erzeugt [(120% der Zaubermacht) + 30] Chi. ]" }
entries[322102] = { ["name"] = "Schadensumleitung", ["text"] = "Die Abklingzeit ist um 10 Sek. verringert und das positive Chi aller Eurer heilenden Sphären wird herangezogen, um die Heilung von 'Schadensumleitung' zu erhöhen." }
entries[322103] = { ["name"] = "Liebkosung des Lichts", ["text"] = "Unbegrenzte Reichweite\nSofort\nSobald Verbündete den Effekt Eures Zaubers 'Machtwort: Barriere' erhalten, werden sie um (100% der Zaubermacht) Gesundheit geheilt. Wenn sie sich bei Ablauf des Effekts im Wirkungsbereich befinden, werden sie erneut um (100% der Zaubermacht) Gesundheit geheilt." }
