entries[322105] = { ["name"] = "Schattenbündnis", ["text"] = "30 Meter Reichweite\nSofort\nBenötigt Schattengestalt\nBeim Einsatz Eures [ Geistbeuger : Geistbeugers / Schattengeists] geht Ihr einen schattenhaften Pakt ein, der 'Strahlenkranz', 'Göttlicher Stern' und 'Sühne' in Schattenzauber verwandelt sowie den Schaden und die Heilung Eurer Schattenzauber um [ Geistbeuger : 10 / 25 ]% erhöht, solange dieser aktiv ist." }
entries[322109] = { ["name"] = "Berührung des Todes", ["text"] = "Nahkampfreichweite\nSofort 3 min Abklingzeit\nIhr nutzt die größte Schwachstelle des gegnerischen Ziels aus und fügt ihm sofort Schaden in Höhe von 100% Eurer maximalen Gesundheit zu [ Verbesserte Berührung des Todes : wenn es sich um eine Kreatur handelt, die über weniger Gesundheit verfügt als Ihr / .\n\nKann nur gegen Kreaturen eingesetzt werden, die weniger Gesundheit haben als Ihr.] [ Fügt Spielercharakteren sowie stärkeren Kreaturen mit weniger als 15% Gesundheit Schaden in Höhe von 35% Eurer maximalen Gesundheit zu ] [ Berührung des Todes : Verringert den gestaffelten Schaden um 200% des verursachten Schadens ] [ Erzeugt 3 Chisphären, die jeweils 1 Chi erzeugen, wenn Ihr durch sie lauft ] [ Erhöht den körperlichen Schaden des Mönchs für 10 Sek. um 15% ]" }
entries[322111] = { ["name"] = "Berührung des Todes", ["text"] = "100 Meter Reichweite\nSofort\nIhr nutzt die größte Schwachstelle des gegnerischen Ziels aus und fügt ihm sofort Schaden in Höhe von 100% Eurer maximalen Gesundheit zu [ Verbesserte Berührung des Todes : wenn es sich um eine Kreatur handelt, die über weniger Gesundheit verfügt als Ihr / .\n\nKann nur gegen Kreaturen eingesetzt werden, die weniger Gesundheit haben als Ihr.] [ Fügt Spielercharakteren sowie stärkeren Kreaturen mit weniger als 15% Gesundheit Schaden in Höhe von 35% Eurer maximalen Gesundheit zu ] [ Berührung des Todes : Verringert den gestaffelten Schaden um 200% des verursachten Schadens ] [ Erzeugt 3 Chisphären, die jeweils 1 Chi erzeugen, wenn Ihr durch sie lauft ] [ Erhöht den körperlichen Schaden des Mönchs für 10 Sek. um 15% ]" }
